#include "internal.h"
void _picaDrawArrayRaw(GPU_Primitive_t primitive,uint32_t first,uint32_t count);
void _picaDrawElementsRaw(GPU_Primitive_t primitive,uint32_t indexArray,uint32_t count);
static void StereoMatrix(matrix4x4*out,int eye){matrix4x4_multiply(out,&pglState->matrix_projection,&pglState->matrix_modelview);if(pglState->stereoParallax)out->row[0].w+=(eye==0?-1.0f:1.0f)*pglState->stereoSeparation;}
void _picaDrawArray(GPU_Primitive_t primitive,uint32_t first,uint32_t count){if(!pglState->stereoEnabled){_picaRenderBuffer(pglState->colorBuffer[0],pglState->depthBuffer[0]);matrix4x4 m;StereoMatrix(&m,0);_picaUniformFloat(GPU_VERTEX_SHADER,0,(float*)&m,4);_picaDrawArrayRaw(primitive,first,count);return;}for(int eye=0;eye<2;eye++){pglState->activeEye=eye;_picaRenderBuffer(pglState->colorBuffer[eye],pglState->depthBuffer[eye]);matrix4x4 m;StereoMatrix(&m,eye);_picaUniformFloat(GPU_VERTEX_SHADER,0,(float*)&m,4);_picaDrawArrayRaw(primitive,first,count);}}
void _picaDrawElements(GPU_Primitive_t primitive,uint32_t indexArray,uint32_t count){if(!pglState->stereoEnabled){_picaRenderBuffer(pglState->colorBuffer[0],pglState->depthBuffer[0]);matrix4x4 m;StereoMatrix(&m,0);_picaUniformFloat(GPU_VERTEX_SHADER,0,(float*)&m,4);_picaDrawElementsRaw(primitive,indexArray,count);return;}for(int eye=0;eye<2;eye++){pglState->activeEye=eye;_picaRenderBuffer(pglState->colorBuffer[eye],pglState->depthBuffer[eye]);matrix4x4 m;StereoMatrix(&m,eye);_picaUniformFloat(GPU_VERTEX_SHADER,0,(float*)&m,4);_picaDrawElementsRaw(primitive,indexArray,count);}}
